const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Client = require('../models/Client');
const Mailbox = require('../models/Mailbox');
const Otp = require('../models/Otp');
const emailService = require('../services/email.service');
const logger = require('../config/logger');

// Unified Login Route
router.post('/', async (req, res) => {
  try {
    const { email, password } = req.body;

    // 1. Try to find as Client (Admin)
    const client = await Client.findOne({ email });
    if (client) {
      const isMatch = await bcrypt.compare(password, client.password_hash);
      if (isMatch) {
        const token = jwt.sign({ client_id: client._id }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
        return res.json({
          token,
          role: 'client',
          email: client.email,
          first_name: client.first_name,
          last_name: client.last_name,
          company_name: client.company_name
        });
      }
    }

    // 2. Try to find as Mailbox (Webmail User)
    const mailbox = await Mailbox.findOne({ email });
    if (mailbox) {
      const isMatch = await bcrypt.compare(password, mailbox.password_hash);
      if (isMatch) {
        const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
        return res.json({
          token,
          role: 'mailbox',
          email: mailbox.email,
          first_name: mailbox.first_name,
          last_name: mailbox.last_name
        });
      }
    }

    // 3. Neither found
    return res.status(400).json({ error: 'Invalid email or password' });

  } catch (err) {
    logger.error('Unified Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Request Password Reset (Send OTP)
router.post('/forgot-password', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email) return res.status(400).json({ error: 'Email required' });

    // Normalize email
    const emailLower = email.toLowerCase().trim();

    // Check if user exists (Client or Mailbox)
    const client = await Client.findOne({ email: emailLower });
    const mailbox = await Mailbox.findOne({ email: emailLower });

    // Security: Always return success to prevent email enumeration
    if (!client && !mailbox) {
      logger.info(`Forgot Password requested for non-existent email: ${emailLower}`);
      return res.json({ message: 'If that email exists, a verification code has been sent.' });
    }

    // Generate 6-digit OTP
    const otp = Math.floor(100000 + Math.random() * 900000).toString();

    // Save OTP (replaces any existing ones for this email)
    await Otp.deleteMany({ email: emailLower });
    await Otp.create({ email: emailLower, otp });

    // Send Email
    const subject = 'Reset Your Password';
    const text = `Your verification code is: ${otp}. It expires in 10 minutes.`;
    const html = `
      <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; background-color: #f9fafb; border-radius: 10px;">
        <div style="background-color: #fff; padding: 30px; border-radius: 8px; border: 1px solid #e5e7eb;">
          <h2 style="color: #111827; margin-top: 0;">Password Reset Request</h2>
          <p style="color: #4b5563;">You requested to reset the password for <strong>${emailLower}</strong>.</p>
          <p style="color: #4b5563;">Use the verification code below to proceed:</p>
          <div style="background-color: #f3f4f6; padding: 15px; border-radius: 6px; text-align: center; margin: 20px 0;">
            <span style="font-size: 32px; font-weight: bold; letter-spacing: 5px; color: #16a34a;">${otp}</span>
          </div>
          <p style="color: #6b7280; font-size: 14px;">This code expires in 10 minutes.</p>
          <p style="color: #6b7280; font-size: 14px; margin-top: 20px;">If you did not request this change, please ignore this email.</p>
        </div>
      </div>
    `;

    // Use system's own email service to send the recovery email
    await emailService.sendSystemEmail(emailLower, subject, text, html);

    logger.info(`Recovery email sent to ${emailLower}`);
    res.json({ message: 'If that email exists, a verification code has been sent.' });

  } catch (err) {
    logger.error('Forgot Password Error:', err);
    res.status(500).json({ error: 'System error processing request' });
  }
});

// Reset Password (Verify OTP and Update)
router.post('/reset-password', async (req, res) => {
  try {
    const { email, otp, newPassword } = req.body;

    if (!email || !otp || !newPassword) return res.status(400).json({ error: 'Missing fields' });
    if (newPassword.length < 6) return res.status(400).json({ error: 'Password must be at least 6 characters' });

    const emailLower = email.toLowerCase().trim();

    // Verify OTP
    const validOtp = await Otp.findOne({ email: emailLower, otp });
    if (!validOtp) {
      return res.status(400).json({ error: 'Invalid or expired verification code' });
    }

    // Hash new password
    const salt = await bcrypt.genSalt(10);
    const hash = await bcrypt.hash(newPassword, salt);

    // Update User (Try Client first, then Mailbox)
    const client = await Client.findOne({ email: emailLower });
    if (client) {
        client.password_hash = hash;
        await client.save();
    } else {
        const mailbox = await Mailbox.findOne({ email: emailLower });
        if (mailbox) {
            mailbox.password_hash = hash;
            await mailbox.save();
        } else {
             // Should not happen if OTP exists, but handle anyway
             return res.status(400).json({ error: 'User not found' });
        }
    }

    // Cleanup used OTP
    await Otp.deleteOne({ _id: validOtp._id });

    logger.info(`Password reset successfully for ${emailLower}`);
    res.json({ message: 'Password updated successfully. Please sign in.' });

  } catch (err) {
    logger.error('Reset Password Error:', err);
    res.status(500).json({ error: 'Failed to reset password' });
  }
});

