import React, { createContext, useContext, useState, useCallback } from 'react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: number;
  message: string;
  type: ToastType;
}

interface ToastContextType {
  addToast: (message: string, type?: ToastType) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((message: string, type: ToastType = 'success') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);

    // Auto remove after 4 seconds
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  const removeToast = (id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <div className="fixed bottom-4 right-4 z-[9999] flex flex-col gap-2 pointer-events-none">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`pointer-events-auto flex items-center w-full max-w-sm overflow-hidden bg-white rounded-lg shadow-lg border-l-4 animate-in slide-in-from-right-full duration-300 ${
              toast.type === 'success' ? 'border-green-500' : 
              toast.type === 'error' ? 'border-red-500' : 'border-blue-500'
            }`}
          >
            <div className="p-4 flex items-center">
              <div className="flex-shrink-0">
                {toast.type === 'success' && (
                  <svg className="w-5 h-5 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                )}
                {toast.type === 'error' && (
                  <svg className="w-5 h-5 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                )}
                {toast.type === 'info' && (
                  <svg className="w-5 h-5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                )}
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-gray-900">{toast.message}</p>
              </div>
              <div className="ml-4 flex-shrink-0 flex">
                <button
                  onClick={() => removeToast(toast.id)}
                  className="inline-flex text-gray-400 hover:text-gray-500 focus:outline-none"
                >
                  <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (context === undefined) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

import React, { useState } from 'react';
import api from '../api';
import Spinner from '../components/Spinner';
import { User } from '../types';

interface AuthViewProps {
  onSuccess: (user: User) => void;
  onBack: () => void;
}

const AuthView = ({ onSuccess, onBack }: AuthViewProps) => {
  // Mode: 'login' | 'forgot' | 'reset'
  const [mode, setMode] = useState<'login' | 'forgot' | 'reset'>('login');

  // Login State
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Reset State
  const [resetOtp, setResetOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');

  // UI State
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const res = await api.post('/api/login', { email, password });
      const { token, role, email: userEmail, company_name } = res.data;

      localStorage.setItem('smtp_token', token);

      onSuccess({
        email: userEmail,
        company_name: company_name,
        token,
        role: role
      });
    } catch (err: any) {
      setError(err.response?.data?.error || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const handleForgotSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccessMsg('');
    setLoading(true);

    try {
      // Always returns success status for security
      await api.post('/api/login/forgot-password', { email });
      setMode('reset');
      setSuccessMsg(`Verification code sent to ${email}`);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to send code');
    } finally {
      setLoading(false);
    }
  };

  const handleResetSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccessMsg('');
    setLoading(true);

    try {
      await api.post('/api/login/reset-password', { 
        email, 
        otp: resetOtp, 
        newPassword 
      });
      setSuccessMsg('Password updated! Please sign in.');
      setMode('login');
      setPassword('');
      setNewPassword('');
      setResetOtp('');
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to reset password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8 font-sans">
      <div className="sm:mx-auto sm:w-full sm:max-w-md text-center">
        <div className="mx-auto h-12 w-12 bg-green-600 rounded-xl flex items-center justify-center text-white mb-4 shadow-lg shadow-green-200">
             <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
        </div>
        <h2 className="text-3xl font-extrabold text-gray-900 tracking-tight">
          {mode === 'login' && 'Employee Login'}
          {mode === 'forgot' && 'Reset Password'}
          {mode === 'reset' && 'Set New Password'}
        </h2>
        <p className="mt-2 text-center text-sm text-gray-600">
          {mode === 'login' && 'Access your workspace'}
          {mode === 'forgot' && 'Enter your email to receive a code'}
          {mode === 'reset' && 'Check your email for the verification code'}
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow-xl shadow-gray-100 sm:rounded-2xl sm:px-10 border border-gray-100">
            {error && (
              <div className="mb-4 bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg text-sm text-center font-medium animate-in fade-in slide-in-from-top-2">
                {error}
              </div>
            )}
            {successMsg && (
              <div className="mb-4 bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg text-sm text-center font-medium animate-in fade-in slide-in-from-top-2">
                {successMsg}
              </div>
            )}

            {/* LOGIN FORM */}
            {mode === 'login' && (
                <form className="space-y-6" onSubmit={handleLogin}>
                  <div>
                    <label className="block text-sm font-bold text-gray-700">Email address</label>
                    <input type="email" required value={email} onChange={e => setEmail(e.target.value)} 
                      className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500 transition-colors" />
                  </div>

                  <div>
                    <div className="flex justify-between items-center mb-1">
                        <label className="block text-sm font-bold text-gray-700">Password</label>
                        <button type="button" onClick={() => { setError(''); setMode('forgot'); }} className="text-sm text-green-600 hover:text-green-500 font-medium">
                            Forgot?
                        </button>
                    </div>
                    <input type="password" required value={password} onChange={e => setPassword(e.target.value)} 
                      className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500 transition-colors" />
                  </div>

                  <div className="flex items-center justify-between">
                    <div className="text-sm">
                       <button type="button" onClick={onBack} className="font-medium text-gray-500 hover:text-green-600 transition-colors">
                          &larr; Back to Website
                        </button>
                    </div>
                  </div>

                  <button type="submit" disabled={loading}
                    className="w-full flex justify-center py-2.5 px-4 border border-transparent rounded-lg shadow-sm text-sm font-bold text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 transition-colors">
                    {loading ? <Spinner /> : 'Sign In'}
                  </button>
                </form>
            )}

            {/* FORGOT PASSWORD FORM */}
            {mode === 'forgot' && (
                <form className="space-y-6" onSubmit={handleForgotSubmit}>
                  <div>
                    <label className="block text-sm font-bold text-gray-700">Email address</label>
                    <input type="email" required value={email} onChange={e => setEmail(e.target.value)} 
                      placeholder="name@company.com"
                      className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500 transition-colors" />
                  </div>

                  <button type="submit" disabled={loading}
                    className="w-full flex justify-center py-2.5 px-4 border border-transparent rounded-lg shadow-sm text-sm font-bold text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 transition-colors">
                    {loading ? <Spinner /> : 'Send Verification Code'}
                  </button>

                  <div className="text-center">
                    <button type="button" onClick={() => { setError(''); setMode('login'); }} className="text-sm font-medium text-gray-500 hover:text-gray-900">
                        Cancel and return to login
                    </button>
                  </div>
                </form>
            )}

            {/* RESET PASSWORD FORM */}
            {mode === 'reset' && (
                <form className="space-y-6" onSubmit={handleResetSubmit}>
                  <div>
                    <label className="block text-sm font-bold text-gray-700">Verification Code</label>
                    <input type="text" required value={resetOtp} onChange={e => setResetOtp(e.target.value)} 
                      placeholder="123456"
                      className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500 transition-colors font-mono tracking-widest text-center text-lg" />
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700">New Password</label>
                    <input type="password" required value={newPassword} onChange={e => setNewPassword(e.target.value)} 
                      minLength={6}
                      className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500 transition-colors" />
                  </div>

                  <button type="submit" disabled={loading}
                    className="w-full flex justify-center py-2.5 px-4 border border-transparent rounded-lg shadow-sm text-sm font-bold text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 transition-colors">
                    {loading ? <Spinner /> : 'Update Password'}
                  </button>

                  <div className="text-center">
                    <button type="button" onClick={() => { setError(''); setMode('login'); }} className="text-sm font-medium text-gray-500 hover:text-gray-900">
                        Cancel
                    </button>
                  </div>
                </form>
            )}

        </div>
      </div>
    </div>
  );
};

export default AuthView;

import React, { useState, useEffect } from 'react';
import api from '../api';
import { User, Domain, Mailbox, DnsStatus } from '../types';
import { useToast } from '../components/ToastContext';

// Components
import DashboardNavbar from './dashboard/DashboardNavbar';
import ServerInfoPanel from './dashboard/ServerInfoPanel';
import DomainManager from './dashboard/DomainManager';
import MailboxManager from './dashboard/MailboxManager';

// Modals
import DnsConfigModal from './dashboard/modals/DnsConfigModal';
import SystemLogsModal from './dashboard/modals/SystemLogsModal';
import DiagnosticsModal from './dashboard/modals/DiagnosticsModal';
import AccountSettingsModal from './dashboard/modals/AccountSettingsModal';
import EditMailboxModal from './dashboard/modals/EditMailboxModal';

// Types
interface SystemLog {
  _id: string;
  level: string;
  message: string;
  timestamp: string;
  meta?: any;
}

interface DiagnosticResult {
  dns: { status: 'ok' | 'error'; message: string };
  port25: { status: 'ok' | 'error'; message: string };
  timestamp: string;
}

interface Props {
    user: User;
    onLogout: () => void;
    onUserUpdate: (u: Partial<User>) => void;
}

const ClientDashboard = ({ user, onLogout, onUserUpdate }: Props) => {
  const { addToast } = useToast();
  const [domains, setDomains] = useState<Domain[]>([]);
  const [mailboxes, setMailboxes] = useState<Mailbox[]>([]);
  const [newDomain, setNewDomain] = useState('');
  const [loading, setLoading] = useState(false);

  // Mailbox creation state
  const [selectedDomainId, setSelectedDomainId] = useState<string | null>(null);
  const [newMailboxEmail, setNewMailboxEmail] = useState('');
  const [newMailboxPassword, setNewMailboxPassword] = useState('');

  // DNS View State
  const [viewDnsDomain, setViewDnsDomain] = useState<Domain | null>(null);
  const [dnsStatus, setDnsStatus] = useState<DnsStatus | null>(null);
  const [checkingDns, setCheckingDns] = useState(false);

  // Logs View State
  const [showLogs, setShowLogs] = useState(false);
  const [logs, setLogs] = useState<SystemLog[]>([]);

  // Diagnostics View State
  const [showDiagnostics, setShowDiagnostics] = useState(false);
  const [diagnosticResult, setDiagnosticResult] = useState<DiagnosticResult | null>(null);
  const [runningDiagnostics, setRunningDiagnostics] = useState(false);

  // Account Settings State
  const [showAccountSettings, setShowAccountSettings] = useState(false);

  // Edit Mailbox State
  const [editingMailbox, setEditingMailbox] = useState<Mailbox | null>(null);

  const refreshData = async () => {
    try {
      const dRes = await api.get('/api/domains');
      setDomains(dRes.data);
      const mRes = await api.get('/api/mailboxes');
      setMailboxes(mRes.data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => { refreshData(); }, []);

  useEffect(() => {
    let interval: any;
    if (showLogs) {
      fetchLogs();
      interval = setInterval(fetchLogs, 5000);
    }
    return () => clearInterval(interval);
  }, [showLogs]);

  const fetchLogs = async () => {
    try {
      const res = await api.get('/api/system/logs');
      setLogs(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const runDiagnostics = async () => {
    setShowDiagnostics(true);
    setRunningDiagnostics(true);
    setDiagnosticResult(null);
    try {
      const res = await api.get('/api/system/diagnostics');
      setDiagnosticResult(res.data);
    } catch (err) {
      console.error(err);
      addToast('Failed to run diagnostics', 'error');
    } finally {
      setRunningDiagnostics(false);
    }
  };

  const handleAddDomain = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDomain) return;
    try {
      await api.post('/api/domains', { name: newDomain });
      setNewDomain('');
      addToast('Domain added successfully', 'success');
      refreshData();
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Failed to add domain', 'error');
    }
  };

  const handleDeleteDomain = async (id: string) => {
    if(!confirm('Are you sure? This will delete all mailboxes and emails associated with this domain.')) return;
    try {
        await api.delete(`/api/domains/${id}`);
        addToast('Domain deleted', 'success');
        refreshData();
    } catch (err: any) {
        addToast(err.response?.data?.error || 'Failed to delete domain', 'error');
    }
  };

  const handleDeleteMailbox = async (id: string) => {
    if(!confirm('Are you sure you want to delete this mailbox? All messages will be lost.')) return;
    try {
        await api.delete(`/api/mailboxes/${id}`);
        addToast('Mailbox deleted', 'success');
        refreshData();
    } catch(err: any) {
        addToast(err.response?.data?.error || 'Failed to delete mailbox', 'error');
    }
  };

  const handleVerify = async (domainId: string) => {
    setLoading(true);
    try {
      await api.post(`/api/domains/${domainId}/verify`);
      await refreshData();
      addToast('Domain Verified Successfully!', 'success');
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Verification Failed', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateMailbox = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDomainId) return;

    // Get recovery email from form input directly since we don't have separate state for it
    const formData = new FormData(e.target as HTMLFormElement);
    const recoveryEmail = formData.get('recoveryEmail') as string;

    try {
      await api.post(`/api/domains/${selectedDomainId}/mailboxes`, {
        email: newMailboxEmail,
        password: newMailboxPassword,
        recovery_email: recoveryEmail
      });
      setNewMailboxEmail('');
      setNewMailboxPassword('');
      setSelectedDomainId(null);
      addToast('Mailbox created successfully', 'success');
      refreshData();
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Failed to create mailbox', 'error');
    }
  };

  const openDnsModal = async (domain: Domain) => {
    setViewDnsDomain(domain);
    setDnsStatus(null);
    checkDns(domain);
  };

  const checkDns = async (domain: Domain) => {
    setCheckingDns(true);
    try {
      const res = await api.get(`/api/domains/${domain._id}/dns`);
      setDnsStatus(res.data);
    } catch (error) {
      console.error(error);
    } finally {
      setCheckingDns(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 relative pb-20 font-sans">

      {/* Navigation */}
      <DashboardNavbar 
        user={user} 
        onLogout={onLogout} 
        onShowLogs={() => setShowLogs(true)} 
        onOpenSettings={() => setShowAccountSettings(true)}
      />

      <main className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">

        {/* Server Health Panel */}
        <ServerInfoPanel 
          onRunDiagnostics={runDiagnostics} 
        />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Domains Section */}
          <div className="lg:col-span-2 space-y-6">
            <DomainManager 
                domains={domains}
                newDomain={newDomain}
                setNewDomain={setNewDomain}
                onAddDomain={handleAddDomain}
                onDeleteDomain={handleDeleteDomain}
                onVerify={handleVerify}
                onOpenDns={openDnsModal}
                loading={loading}
                selectedDomainId={selectedDomainId}
                setSelectedDomainId={setSelectedDomainId}
                newMailboxEmail={newMailboxEmail}
                setNewMailboxEmail={setNewMailboxEmail}
                newMailboxPassword={newMailboxPassword}
                setNewMailboxPassword={setNewMailboxPassword}
                onCreateMailbox={handleCreateMailbox}
            />
          </div>

          {/* Mailboxes Section */}
          <div className="space-y-6">
            <MailboxManager 
                mailboxes={mailboxes} 
                onDeleteMailbox={handleDeleteMailbox}
                onEditMailbox={(mb) => setEditingMailbox(mb)}
            />
          </div>

        </div>
      </main>

      {/* MODALS */}
      {viewDnsDomain && (
        <DnsConfigModal 
            domain={viewDnsDomain}
            status={dnsStatus}
            checking={checkingDns}
            onClose={() => setViewDnsDomain(null)}
            onRefresh={() => checkDns(viewDnsDomain)}
        />
      )}

      {showLogs && (
        <SystemLogsModal 
            logs={logs}
            onClose={() => setShowLogs(false)}
            onRefresh={fetchLogs}
        />
      )}

      {showDiagnostics && (
        <DiagnosticsModal 
            result={diagnosticResult}
            running={runningDiagnostics}
            onClose={() => !runningDiagnostics && setShowDiagnostics(false)}
        />
      )}

      {showAccountSettings && (
        <AccountSettingsModal
            user={user}
            onClose={() => setShowAccountSettings(false)}
            onUpdate={(u) => {
                onUserUpdate(u);
                addToast('Account updated', 'success');
            }}
        />
      )}

      {editingMailbox && (
        <EditMailboxModal 
            mailbox={editingMailbox}
            onClose={() => setEditingMailbox(null)}
            onSuccess={() => { 
                setEditingMailbox(null); 
                refreshData(); 
                addToast('Mailbox updated', 'success');
            }}
        />
      )}

    </div>
  );
};

export default ClientDashboard;

import React, { useState, useEffect, useCallback } from 'react';
import api from '../api';
import { User, EmailMessage } from '../types';
import { useToast } from '../components/ToastContext';

// Import New Modular Components
import WebmailSidebar from './webmail/WebmailSidebar';
import WebmailMessageList from './webmail/WebmailMessageList';
import WebmailReadingPane from './webmail/WebmailReadingPane';
import WebmailMobileNav from './webmail/WebmailMobileNav';
import WebmailCompose from './webmail/WebmailCompose';
import WebmailSettings from './webmail/WebmailSettings';

const WebmailView = ({ user, onLogout }: { user: User, onLogout: () => void }) => {
  const { addToast } = useToast();

  // Data State
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [selectedMsg, setSelectedMsg] = useState<EmailMessage | null>(null);

  // View State
  const [view, setView] = useState<'inbox' | 'sent'>('inbox');
  const [loadingMessages, setLoadingMessages] = useState(false);

  // Pagination State
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalMessages, setTotalMessages] = useState(0);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modals State
  const [showCompose, setShowCompose] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Compose Pre-fill State (for replies)
  const [composeTo, setComposeTo] = useState('');
  const [composeSubject, setComposeSubject] = useState('');

  // Fetch Messages
  const fetchMessages = useCallback(async (isPolling = false) => {
    if (!isPolling) setLoadingMessages(true);
    try {
      const res = await api.get('/api/webmail/messages', {
        params: { folder: view, page, limit: 20 }
      });
      setMessages(res.data.messages);
      setTotalPages(res.data.pagination.pages);
      setTotalMessages(res.data.pagination.total);
    } catch (err) {
      console.error(err);
    } finally {
      if (!isPolling) setLoadingMessages(false);
    }
  }, [view, page]);

  useEffect(() => {
    fetchMessages();
    let int: any;
    if (page === 1) {
        int = setInterval(() => fetchMessages(true), 15000);
    }
    return () => clearInterval(int);
  }, [fetchMessages, page]);

  // Reset state on view change
  useEffect(() => {
      setPage(1);
      setSelectedIds(new Set());
      setSelectedMsg(null);
  }, [view]);

  // Handlers
  const handleSelectMessage = async (msg: EmailMessage) => {
    setSelectedMsg(msg);
    if (!msg.is_read) {
        setMessages(prev => prev.map(m => m._id === msg._id ? { ...m, is_read: true } : m));
        try { await api.patch(`/api/webmail/messages/${msg._id}/read`); } catch (err) {}
    }
  };

  const toggleSelection = (id: string, e: React.SyntheticEvent) => {
    e.stopPropagation();
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === messages.length) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(messages.map(m => m._id)));
    }
  };

  const handleBatchDelete = async () => {
    if(!confirm(`Delete ${selectedIds.size} messages?`)) return;
    try {
        await api.post('/api/webmail/messages/batch-delete', { ids: Array.from(selectedIds) });
        addToast('Messages deleted', 'success');
        setSelectedIds(new Set());
        fetchMessages();
        if (selectedMsg && selectedIds.has(selectedMsg._id)) {
            setSelectedMsg(null);
        }
    } catch (err) {
        addToast('Failed to delete messages', 'error');
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if(!confirm('Delete this message?')) return;
    try {
        await api.delete(`/api/webmail/messages/${id}`);
        setMessages(prev => prev.filter(m => m._id !== id));
        if (selectedMsg?._id === id) setSelectedMsg(null);
        addToast('Message deleted', 'success');
    } catch(err) {
        addToast('Failed to delete message', 'error');
        fetchMessages();
    }
  };

  const handleReply = () => {
    if (!selectedMsg) return;
    const replyTo = view === 'inbox' ? selectedMsg.from : selectedMsg.to;
    const replySubject = selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`;

    // Injecting content into the compose window via DOM manipulation is tricky with state separation.
    // We will pass the subject/to and let the user type. 
    // In a full implementation, we'd pass the html body to the compose component.
    // For now, let's keep it simple as requested for structure.

    setComposeTo(replyTo);
    setComposeSubject(replySubject);
    setShowCompose(true);

    // Hack to inject quote if needed, or we rely on user manually quoting for now.
    // The Compose component handles fresh state.

    // We can try to update the content after render, but let's stick to clean props first.
    setTimeout(() => {
        const editor = document.getElementById('compose-editor');
        if (editor) {
            const quoteHtml = `<br><br><blockquote style="border-left: 2px solid #ccc; padding-left: 10px; margin-left: 5px; color: #666;">
            On ${new Date(selectedMsg.created_at).toLocaleString()}, <strong>${selectedMsg.from}</strong> wrote:<br>
            ${selectedMsg.html_body || selectedMsg.text_body}
            </blockquote><br>`;
            editor.innerHTML = quoteHtml;
            // focus logic if needed
        }
    }, 100);
  };

  const handleCompose = () => {
      setComposeTo('');
      setComposeSubject('');
      setShowCompose(true);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* 1. Desktop Sidebar */}
      <WebmailSidebar 
        user={user}
        view={view}
        messages={messages}
        onCompose={handleCompose}
        onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
        onSettings={() => setShowSettings(true)}
        onLogout={onLogout}
      />

      {/* 2. Message List */}
      <WebmailMessageList 
        user={user}
        messages={messages}
        selectedMsg={selectedMsg}
        onSelect={handleSelectMessage}
        view={view}
        loading={loadingMessages}
        onRefresh={() => fetchMessages()}
        selectedIds={selectedIds}
        toggleSelectAll={toggleSelectAll}
        toggleSelection={toggleSelection}
        onBatchDelete={handleBatchDelete}
        page={page}
        totalPages={totalPages}
        setPage={setPage}
        totalMessages={totalMessages}
      />

      {/* 3. Reading Pane */}
      <WebmailReadingPane 
        selectedMsg={selectedMsg}
        onBack={() => setSelectedMsg(null)}
        onDelete={handleDelete}
        onReply={handleReply}
      />

      {/* 4. Mobile Bottom Navigation */}
      {/* Hide nav if reading a message to allow full screen reading */}
      {!selectedMsg && (
          <WebmailMobileNav 
            view={view}
            onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
            onCompose={handleCompose}
            onSettings={() => setShowSettings(true)}
            showSettings={showSettings}
          />
      )}

      {/* 5. Compose Modal */}
      <WebmailCompose 
        show={showCompose}
        onClose={() => setShowCompose(false)}
        initialTo={composeTo}
        initialSubject={composeSubject}
        onSuccess={() => {
            if (view === 'sent') fetchMessages();
        }}
      />

      {/* 6. Settings Modal */}
      {showSettings && (
        <WebmailSettings 
            user={user}
            onClose={() => setShowSettings(false)}
            onLogout={onLogout}
        />
      )}

    </div>
  );
};

export default WebmailView;

